import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.7w-lhQN6.js";const u=JSON.parse('{"title":"Global Actions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/global-actions.md","filePath":"guide/global-actions.md","lastUpdated":1793550481000}'),n={name:"guide/global-actions.md"};function i(l,e,d,r,h,c){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="global-actions" tabindex="-1">Global Actions <a class="header-anchor" href="#global-actions" aria-label="Permalink to &quot;Global Actions&quot;">​</a></h1><p>After this page you can unlock global actions for Claude Code and/or Codex, turn off a <code>remove</code> or <code>filter-server</code> recommendation from the <a href="/MCPLens/guide/reading-reports">report</a> without hand-editing a config file, and restore it if you change your mind.</p><p>Global actions live entirely in the <a href="/MCPLens/guide/vscode-extension">VS Code extension</a>. Every step on this page is a VS Code command, and the CLI has no equivalent. On the CLI-only path, act on a report row by editing the client config yourself; the two blocks under <a href="#disable-a-tool-globally">Disable a tool globally</a> show the exact rule the extension would write.</p><h2 id="what-a-global-action-is" tabindex="-1">What a global action is <a class="header-anchor" href="#what-a-global-action-is" aria-label="Permalink to &quot;What a global action is&quot;">​</a></h2><p>A global action edits your client&#39;s config so a tool is unavailable in every session, not just the current one. It is the step after the report tells you a tool is safe to drop.</p><table tabindex="0"><thead><tr><th>Client</th><th>Global actions</th></tr></thead><tbody><tr><td>Claude Code</td><td>supported</td></tr><tr><td>Codex</td><td>supported</td></tr><tr><td>Gemini CLI</td><td>not supported</td></tr></tbody></table><p>Gemini CLI is excluded outright: it is never offered as a target, regardless of the rollout setting below.</p><h2 id="global-actions-are-locked-by-default" tabindex="-1">Global actions are locked by default <a class="header-anchor" href="#global-actions-are-locked-by-default" aria-label="Permalink to &quot;Global actions are locked by default&quot;">​</a></h2><p>The setting <code>mcplens.dependencyAnalysis.rollout</code> controls this, and its default is <code>&quot;off&quot;</code>. With it off, MCP Lens computes recommendations and shows them in the report and sidebar as usual, but it never edits a client config file.</p><table tabindex="0"><thead><tr><th>Value</th><th>Effect</th></tr></thead><tbody><tr><td><code>off</code> (default)</td><td>Global actions are locked. Lens never edits your client config.</td></tr><tr><td><code>claude</code></td><td>Allow global actions for Claude Code only.</td></tr><tr><td><code>codex</code></td><td>Allow global actions for Codex only.</td></tr><tr><td><code>all</code></td><td>Allow global actions for Claude Code and Codex.</td></tr></tbody></table><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>Run the command <strong>MCP Lens: Open Global Actions Setting</strong> from the Command Palette (<code>Cmd/Ctrl+Shift+P</code>) and it jumps straight to <code>mcplens.dependencyAnalysis.rollout</code> in Settings. Pick <code>claude</code>, <code>codex</code>, or <code>all</code> there.</p><p>Alternatively, set it directly in <code>settings.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcplens.dependencyAnalysis.rollout&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;all&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="run-the-dependency-analysis-first" tabindex="-1">Run the dependency analysis first <a class="header-anchor" href="#run-the-dependency-analysis-first" aria-label="Permalink to &quot;Run the dependency analysis first&quot;">​</a></h2><p><strong>MCP Lens: Disable Globally</strong> refuses on any tool the dependency analysis has not judged yet: it re-reads the stored analysis result for the tool right before it edits anything, and treats a missing result as &quot;Review required&quot;, which is not eligible. So run <strong>MCP Lens: Analyze Dependencies</strong> (or let the onboarding walkthrough&#39;s third step do it) before you try to disable anything.</p><h2 id="disable-a-tool-globally" tabindex="-1">Disable a tool globally <a class="header-anchor" href="#disable-a-tool-globally" aria-label="Permalink to &quot;Disable a tool globally&quot;">​</a></h2><p>With the rollout set and the analysis done, open the MCP Lens sidebar tree, select the tool you want to turn off, and run <strong>MCP Lens: Disable Globally</strong>. The exact file it edits depends on the client the tool belongs to.</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-Iz1rt" id="tab-DIH9BIQ" checked><label data-title="~/.claude/settings.json" for="tab-DIH9BIQ">~/.claude/settings.json</label><input type="radio" name="group-Iz1rt" id="tab-wOlzYuH"><label data-title="~/.codex/config.toml" for="tab-wOlzYuH">~/.codex/config.toml</label></div><div class="blocks"><div class="language-jsonc vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;permissions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;deny&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;mcp__web-search__web-search_place_search&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp_servers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">web-search</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">disabled_tools = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;web-search_place_search&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div></div></div><p>You do not write these yourself; MCP Lens adds the one rule for the one tool you picked, backs up the file first, and records the change so it can later remove exactly that rule and nothing else.</p><h2 id="why-a-tool-can-be-ineligible" tabindex="-1">Why a tool can be ineligible <a class="header-anchor" href="#why-a-tool-can-be-ineligible" aria-label="Permalink to &quot;Why a tool can be ineligible&quot;">​</a></h2><p><strong>MCP Lens: Disable Globally</strong> can refuse even with the rollout on, most often because the dependency analysis has not marked the tool <code>Independent</code> yet, or because the same server name resolves to different commands/URLs across your config sources (an identity conflict Lens will not guess through). Re-run <strong>MCP Lens: Analyze Dependencies</strong> or resolve the naming conflict, then try again.</p><h2 id="restore-a-tool" tabindex="-1">Restore a tool <a class="header-anchor" href="#restore-a-tool" aria-label="Permalink to &quot;Restore a tool&quot;">​</a></h2><p>Run <strong>MCP Lens: Restore Globally</strong> on a disabled tool to remove the rule Lens added. If you edited that config file yourself in the meantime and it no longer matches what Lens recorded, the restore is refused with a conflict rather than silently overwriting your edit.</p><h2 id="caveats-worth-knowing" tabindex="-1">Caveats worth knowing <a class="header-anchor" href="#caveats-worth-knowing" aria-label="Permalink to &quot;Caveats worth knowing&quot;">​</a></h2><ul><li><strong>Claude Code&#39;s <code>bypassPermissions</code> mode</strong> can skip the permission-rule layer entirely, so a global deny is not an absolute guarantee under that mode.</li><li><strong>Codex</strong> applies <code>disabled_tools</code> after <code>enabled_tools</code>; an organization-managed policy that takes precedence over your user config can make a Lens rule not apply, in which case Lens reports the client as policy-restricted rather than pretending the write succeeded.</li></ul>`,26)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
